dtsPropsFor.Button:
/** Visual style. Defaults to "default" (indigo primary). */
  variant?: "default" | "accent" | "success" | "outline" | "secondary" | "ghost" | "destructive" | "link";
  /** Height/padding scale. `icon*` sizes render a square icon-only button. */
  size?: "default" | "xs" | "sm" | "lg" | "icon" | "icon-xs" | "icon-sm" | "icon-lg";
  disabled?: boolean;
  type?: "button" | "submit" | "reset";
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Card:
/** `sm` tightens the internal --card-spacing scale. */
  size?: "default" | "sm";
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Input:
type?: React.HTMLInputTypeAttribute;
  placeholder?: string;
  value?: string | number;
  defaultValue?: string | number;
  disabled?: boolean;
  /** Set to render the destructive border + ring error state. */
  "aria-invalid"?: boolean | "true" | "false";
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
  className?: string;

dtsPropsFor.Skeleton:
/** Size and shape come entirely from utility classes, e.g. `h-4 w-3/4`, `size-10 rounded-full`. */
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Switch:
/** Controlled checked state. Use `defaultChecked` for uncontrolled. */
  checked?: boolean;
  defaultChecked?: boolean;
  disabled?: boolean;
  readOnly?: boolean;
  required?: boolean;
  name?: string;
  onCheckedChange?: (checked: boolean, eventDetails: unknown) => void;
  className?: string;

dtsPropsFor.Tabs:
/** Value of the initially selected tab (uncontrolled). */
  defaultValue?: string | number;
  /** Controlled selected tab value. */
  value?: string | number;
  onValueChange?: (value: string | number, eventDetails: unknown) => void;
  orientation?: "horizontal" | "vertical";
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.AudioPlayer:
/** Audio source URL. */
  src: string;
  /** `compact` is the inline row used inside runners; `full` is the standalone player. */
  variant?: "compact" | "full";

dtsPropsFor.GoalPicker:
/** Currently selected goal, or null when nothing is chosen yet. Fully controlled. */
  value: { goalType: "IELTS" | "CEFR" | "TOEIC"; goalValue: string } | null;
  onChange: (value: { goalType: "IELTS" | "CEFR" | "TOEIC"; goalValue: string }) => void;

dtsPropsFor.QuestionCard:
question: {
  id: string;
  number: number;
  prompt: string;
  options: { label: string; text: string }[] | null;
  imageUrl?: string | null;
  kind: "FILL_BLANK" | "MULTIPLE_CHOICE" | "TRANSFORMATION" | "ERROR_CORRECTION" | "TRANSLATION" | "OPEN_WRITING";
  isOpenEnded: boolean;
  errorSpan?: { start: number; end: number } | null;
};
disabled: boolean;
/** Runner phase — drives the correct/incorrect styling. Defaults to "answering" (neutral). */
status?: "answering" | "checking" | "correct" | "incorrect" | "finished";
onChangeInput: (value: string) => void;
emphasizePrompt?: boolean;

dtsPropsFor.SectionedListeningRunner:
/** Listening-set slug; used to POST answers to `/api/listening/<slug>/check`. */
slug: string;
/** All sections, answered one at a time. An empty array renders the "chưa có câu hỏi" fallback. */
sections: {
  label: string;
  title: string;
  instructions: string | null;
  /** Per-section audio, when the set splits its audio by section. */
  audioUrl?: string | null;
  questions: {
    id: string;
    number: number;
    prompt: string;
    options: { label: string; text: string }[] | null;
    kind: "FILL_BLANK" | "MULTIPLE_CHOICE" | "TRANSFORMATION" | "ERROR_CORRECTION" | "TRANSLATION" | "OPEN_WRITING";
    isOpenEnded: boolean;
  }[];
}[];
/** Fires once per section transition, with the newly-shown section index. */
onSectionChange?: (sectionIndex: number) => void;
/** Fires once when a section's answers have been graded. */
onSectionSubmitted?: (sectionIndex: number) => void;
/** Fires when the learner presses "Làm lại" on the finished screen. */
onReset?: () => void;

dtsPropsFor.AppHeader:
className?: string;
/** Link component for the logo link. Pass `NextLink` in the app, `"a"` in a design. No default: omitting it would silently downgrade the link to a full page load. */
linkComponent: React.ElementType;
/** Rendered far right. The app passes <LogoutButton variant="ghost" />. */
logoutSlot: React.ReactNode;

dtsPropsFor.MobileTabBar:
/** Link component. Pass `NextLink` in the app, `"a"` in a design. Required — no default: a default would silently downgrade every tab to a full page load. */
  linkComponent: React.ElementType;
  /** Current pathname, e.g. "/listening/bai-01". A tab is active when the path equals or nests under its href. */
  activePath: string;
  className?: string;

dtsPropsFor.AppSidebar:
name: string | null;
email: string;
/** Placement band, e.g. 6.5. `null` renders "Chưa xếp hạng". */
band: number | null;
/** Current route, e.g. "/listening". Drives nav highlighting. */
pathname: string;
/** Link component. Pass `NextLink` in the app, `"a"` in a design. No default — see AppHeader. */
linkComponent: React.ElementType;

dtsPropsFor.EmptyState:
/** Emoji shown in the soft tile. Defaults to "🌱". */
  icon?: string;
  title: string;
  description?: string;
  /** CTA link target. Both ctaHref and ctaLabel must be set for the button to render. */
  ctaHref?: string;
  ctaLabel?: string;
  /** Link component. Pass `NextLink` in the app, `"a"` in a design. Required — no default. */
  linkComponent: React.ElementType;

dtsPropsFor.LevelBadge:
/** CEFR level; selects the label + semantic-token pill colour from LEVEL_META. */
  level: "A2" | "B1" | "B2" | "C1";
  className?: string;

dtsPropsFor.ListeningSetCard:
href: string;
title: string;
questionCount: number;
/** Pre-formatted, e.g. "8:20". Omit to hide. */
durationLabel?: string;
/** Link component. Pass `NextLink` in the app, `"a"` in a design. Required — no default. */
linkComponent: React.ElementType;
className?: string;

dtsPropsFor.PlacementWizard:
/** Listening section data, or null when listening is not yet available. */
listening: {
  audioUrl: string;
  durationSec: number | null;
  sections: {
    label: string;
    title: string;
    instructions: string | null;
    questions: {
      id: string;
      number: number;
      prompt: string;
      options: { label: string; text: string }[] | null;
      kind: "FILL_BLANK" | "MULTIPLE_CHOICE" | "TRANSFORMATION" | "ERROR_CORRECTION" | "TRANSLATION" | "OPEN_WRITING";
      isOpenEnded: boolean;
    }[];
  }[];
} | null;
/** Reading passage markdown. */
readingMd: string;
readingSections: {
  label: string;
  title: string;
  instructions: string | null;
  questions: {
    id: string;
    number: number;
    prompt: string;
    options: { label: string; text: string }[] | null;
    kind: "FILL_BLANK" | "MULTIPLE_CHOICE" | "TRANSFORMATION" | "ERROR_CORRECTION" | "TRANSLATION" | "OPEN_WRITING";
    isOpenEnded: boolean;
  }[];
}[];
writingPromptMd: string;
/** Called after `/api/placement/complete` succeeds. The app navigates to the result page; a design passes a no-op. Required. */
onFinished: () => void;

dtsPropsFor.ListeningSetView:
slug: string;
/** URL of the listening audio. */
audioUrl: string;
/** Transcript markdown; `Speaker: line` rows are colourised per speaker. */
transcriptMd: string;
sections: {
  label: string;
  title: string;
  instructions: string | null;
  questions: {
    id: string;
    number: number;
    prompt: string;
    options: { label: string; text: string }[] | null;
    kind: "FILL_BLANK" | "MULTIPLE_CHOICE" | "TRANSFORMATION" | "ERROR_CORRECTION" | "TRANSLATION" | "OPEN_WRITING";
    isOpenEnded: boolean;
  }[];
}[];

dtsPropsFor.ErrorState:
/** Headline. Defaults to "Đã có lỗi xảy ra". */
  title?: string;
  /** Body copy under the headline. Has a Vietnamese default. */
  description?: string;
  /** Retry handler — the app passes the error boundary's `reset()`. */
  reset: () => void;
  /** Link component. Pass `NextLink` in the app, `"a"` in a design. Required — no default: a default would silently downgrade every link to a full page load. */
  linkComponent: React.ElementType;

dtsPropsFor.ExerciseRunner:
exerciseId: string;
attemptId: string;
/** 1-based question number to resume on. */
initialQuestionNumber: number;
questions: {
  id: string;
  number: number;
  prompt: string;
  options: { label: string; text: string }[] | null;
  imageUrl?: string | null;
  kind: "FILL_BLANK" | "MULTIPLE_CHOICE" | "TRANSFORMATION" | "ERROR_CORRECTION" | "TRANSLATION" | "OPEN_WRITING";
  isOpenEnded: boolean;
  errorSpan?: { start: number; end: number } | null;
}[];
/** Shown on the finish screen as the newly unlocked lesson; `null` = end of curriculum. */
nextLesson: { slug: string; phaseSlug: string; title: string } | null;
/** Where the top bar's ✕ navigates back to (the lesson overview). */
backHref: string;
/** Questions answered in a PRIOR session, hydrated from the server so "← Câu trước" works on resume. */
initialPast?: { index: number; answerText: string; correctAnswer?: string | null; keyNote?: string | null }[];
/** Link component. Pass `NextLink` in the app, `"a"` in a design. Required — no default: a default would silently downgrade every link to a full page load. */
linkComponent: React.ElementType;

dtsPropsFor.IeltsHub:
/** Every IELTS test, numbered. `isComplete: false` dims the tile. */
tests: { number: number; isComplete: boolean }[];
/** Skill tab selected on first render. Defaults to "reading". */
initialSkill?: "reading" | "writing" | "speaking";
/** Link component. Pass `NextLink` in the app, `"a"` in a design. Required — no default: a default would silently downgrade every link to a full page load. */
linkComponent: React.ElementType;

dtsPropsFor.InlineExample:
/** Lesson the example belongs to; used to POST to `/api/lessons/<id>/example-check`. */
lessonId: string;
/** Answer-free example. The answer is never shipped to the client — checking and revealing both go through the server. */
example: { id: string; prompt: string; hint: string };

dtsPropsFor.LessonMap:
phases: {
  id: string;
  slug: string;
  title: string;
  cefrLabel: string;
  orderIndex: number;
  lessons: { id: string; slug: string; title: string; orderIndex: number }[];
}[];
/** Lesson id -> state. Drives the three phase row variants (completed / locked / active). */
states: Map<string, "LOCKED" | "UNLOCKED" | "COMPLETED" | "SKIPPED">;
/** Link component. Pass `NextLink` in the app, `"a"` in a design. Required — no default: a default would silently downgrade every link to a full page load. */
linkComponent: React.ElementType;

dtsPropsFor.LessonNode:
/** Pill variant: ✓ done, ▶ current, ⏭ skipped, 🔒 locked (not clickable). */
state: "COMPLETED" | "UNLOCKED" | "LOCKED" | "SKIPPED";
/** Pill text, e.g. "Bài 3". */
label: string;
/** Omit (or use state="LOCKED") to render a non-interactive pill. */
href?: string;
/** Native tooltip — the app passes the full lesson title. */
title?: string;
className?: string;
/** Link component. Pass `NextLink` in the app, `"a"` in a design. Required — no default: a default would silently downgrade every link to a full page load. */
linkComponent: React.ElementType;

dtsPropsFor.LessonTabs:
/** Kicker above the title, e.g. "Giai đoạn 2 · A2". */
phaseTitle: string;
lessonTitle: string;
/** The lecture page's own URL; the exercise tab appends "/exercise". */
basePath: string;
active: "lecture" | "exercise";
/** Link component. Pass `NextLink` in the app, `"a"` in a design. Required — no default: a default would silently downgrade every link to a full page load. */
linkComponent: React.ElementType;

dtsPropsFor.ListeningBottomNav:
/** Link component. Pass `NextLink` in the app, `"a"` in a design. Required — no default: a default would silently downgrade every link to a full page load. */
linkComponent: React.ElementType;
/** Optional right-hand hint, e.g. "Phần 2/4". */
subtitle?: string;

dtsPropsFor.PhasePillRow:
/** Every lesson of the active phase, in order. */
lessons: {
  id: string;
  orderIndex: number;
  title: string;
  state: "LOCKED" | "UNLOCKED" | "COMPLETED" | "SKIPPED";
  href: string;
}[];
/** Lesson count shown on the "Xem tất cả N bài" toggle. */
total: number;
/** Link component. Pass `NextLink` in the app, `"a"` in a design. Required — no default: a default would silently downgrade every link to a full page load. */
linkComponent: React.ElementType;

dtsPropsFor.Flashcards:
words: {
  id: string;
  word: string;
  ipa: string;
  meaningVi: string;
  exampleEn: string;
  groupName: string;
}[];
/** "Quay lại từ vựng" target on the finish screen. */
backHref: string;
/** Link component. Pass `NextLink` in the app, `"a"` in a design. Required — no default: a default would silently downgrade every link to a full page load. */
linkComponent: React.ElementType;

dtsPropsFor.MatchGame:
/** Words with an empty `meaningVi` are filtered out; fewer than 2 usable words renders the "chưa đủ từ vựng" fallback. */
words: { id: string; word: string; meaningVi: string }[];
/** "Quay lại từ vựng" target on the finish screen. */
backHref: string;
/** Namespaces the best-time entry in localStorage. */
lessonId: string;
/** Link component. Pass `NextLink` in the app, `"a"` in a design. Required — no default: a default would silently downgrade every link to a full page load. */
linkComponent: React.ElementType;

dtsPropsFor.QuizGame:
/** Words with an empty `meaningVi` are filtered out; too few renders the "chưa đủ từ vựng" fallback. */
words: { id: string; word: string; meaningVi: string }[];
/** "Quay lại từ vựng" target on the finish screen. */
backHref: string;
/** Link component. Pass `NextLink` in the app, `"a"` in a design. Required — no default: a default would silently downgrade every link to a full page load. */
linkComponent: React.ElementType;

dtsPropsFor.LogoutButton:
/** Invoked on click. The connected wrapper calls NextAuth's `signOut`. */
onLogout: () => void;
/** Disables the button and swaps the label while signing out. */
pending?: boolean;
className?: string;
/** Defaults to "outline". */
variant?: "outline" | "ghost" | "destructive";

dtsPropsFor.ResetToStartButton:
/** Invoked on click. The wrapper posts to `/api/placement/reset-to-start`, then navigates. */
onReset: () => void;
pending?: boolean;
/** Failure message shown under the button; `null` when there is none. */
error?: string | null;

dtsPropsFor.SettingsGoalForm:
/** Currently selected goal; `null` when the user has none yet. */
value: { goalType: "IELTS" | "CEFR" | "TOEIC"; goalValue: string } | null;
onChange: (value: { goalType: "IELTS" | "CEFR" | "TOEIC"; goalValue: string }) => void;
/** Invoked by "Lưu thay đổi". The wrapper does the POST. */
onSubmit: () => void;
pending?: boolean;
/** Outcome of the last save: drives the confirmation / error line. */
status?: "idle" | "saved" | "error";

dtsPropsFor.SettingsNameEditor:
/** The persisted display name; `null` falls back to the email. */
name: string | null;
email: string;
/** Invoked with the trimmed, non-empty name. The wrapper does the POST. */
onSave: (name: string) => void;
pending?: boolean;
/** Last save succeeded — shows "✓ Đã lưu" and closes edit mode. */
saved?: boolean;
/** Last save failed — shows the error line. */
error?: boolean;
/** Start in edit mode. Exists so a design can show the edit state statically. */
defaultEditing?: boolean;

dtsPropsFor.ThemeToggleRow:
/** `true` when dark mode is on. */
checked: boolean;
onCheckedChange: (checked: boolean) => void;
